-- query: Anomalies ISL 1 Station_Jen
-- type:  MAKE_TABLE
-- source: CalCOFI_4903-2304_Master_Final_through_2105_October162023.accdb (ACE12), extracted via Jackcess

SELECT [Anomalies ISL 0 IM].Cruise, St_Stations.Code_Region, St_Stations.[Code-SCB], St_Stations.[Code-Nearshore], [Anomalies ISL 0 IM].Sta_ID, Station_ID.St_Line, Station_ID.St_Sta, Station_ID.Distance, [Anomalies ISL 0 IM].Cast_ID, [Anomalies ISL 0 IM].Year AS Year, Cast.Quarter, Avg([Anomalies ISL 0 IM].YearValue) AS YearValue, Avg([Anomalies ISL 0 IM].Date) AS Date, Avg([Anomalies ISL 0 IM].Julian_Day) AS Julian_Day, Avg([Anomalies ISL 0 IM].Time) AS Time, [Anomalies ISL 0 IM].Depth, Avg([Anomalies ISL 0 IM].Temp) AS Temp, Avg([Anomalies ISL 0 IM].Sal) AS Sal, Avg([Anomalies ISL 0 IM].STheta) AS Density, Avg([Anomalies ISL 0 IM].O2) AS O2, [Anomalies ISL 0 IM].NO3 AS NO3, [Anomalies ISL 0 IM].PO4 AS PO4, [Anomalies ISL 0 IM].SiO3 AS SiO3, Avg([Anomalies ISL 0 IM].O2Sat) AS O2Sat, Avg([Anomalies ISL 0 IM].Chla) AS Chla, Avg([Anomalies ISL 0 IM].TempStDev) AS TempStDev, Avg([Anomalies ISL 0 IM].SalStDev) AS SalStDev, Avg([Anomalies ISL 0 IM].SigStDev) AS DensStDev, Avg([Anomalies ISL 0 IM].O2StDev) AS O2StDev, Avg([Anomalies ISL 0 IM].O2SatStDev) AS O2SatStDev, Avg([Anomalies ISL 0 IM].ChlaStDev) AS ChlaStDev, Avg([Anomalies ISL 0 IM].NO3StDev) AS NO3StDev, Avg([Anomalies ISL 0 IM].NO2StDev) AS NO2StDev, Avg([Anomalies ISL 0 IM].PO4StDev) AS PO4StDev, Avg([Anomalies ISL 0 IM].SiO3StDev) AS SiO3StDev, Avg([Anomalies ISL 0 IM].TempAnom) AS TempAnom, Avg([Anomalies ISL 0 IM].SalAnom) AS SalAnom, Avg([Anomalies ISL 0 IM].SigAnom) AS DensAnom, Avg([Anomalies ISL 0 IM].O2Anom) AS O2Anom, Avg([Anomalies ISL 0 IM].O2SatAnom) AS O2SatAnom, Avg([Anomalies ISL 0 IM].ChlaAnom) AS ChlaAnom, Avg([Anomalies ISL 0 IM].NO3Anom) AS NO3Anom, Avg([Anomalies ISL 0 IM].PO4Anom) AS PO4Anom, Avg([Anomalies ISL 0 IM].SIO3Anom) AS SIO3Anom, ([TempAnom]/[TempStDev]) AS TempStAnom, ([SalAnom]/[SalStDev]) AS SalStAnom, ([DensAnom]/[DensStDev]) AS DensStAnom, ([O2Anom]/[O2StDev]) AS O2StAnom, ([O2SatAnom]/[O2SatStDev]) AS O2SatStAnom, ([ChlaAnom]/[ChlaStDev]) AS ChlaStAnom, ([NO3Anom]/[NO3StDev]) AS NO3StAnom, ([PO4Anom]/[PO4StDev]) AS PO4StAnom, ([SiO3Anom]/[SiO3StDev]) AS SiO3StAnom, " " AS Spice, ((([NO3]-16*[PO4]+2.9))) AS NStar INTO Anom_ISL_1_Jen_all
FROM Cast INNER JOIN (St_Stations INNER JOIN (Station_ID INNER JOIN [Anomalies ISL 0 IM] ON Station_ID.Sta_ID = [Anomalies ISL 0 IM].Sta_ID) ON St_Stations.Sta_ID = Station_ID.Sta_ID) ON Cast.Cast_ID = [Anomalies ISL 0 IM].Cast_ID
GROUP BY [Anomalies ISL 0 IM].Cruise, St_Stations.Code_Region, St_Stations.[Code-SCB], St_Stations.[Code-Nearshore], [Anomalies ISL 0 IM].Sta_ID, Station_ID.St_Line, Station_ID.St_Sta, Station_ID.Distance, [Anomalies ISL 0 IM].Cast_ID, [Anomalies ISL 0 IM].Year, Cast.Quarter, [Anomalies ISL 0 IM].Depth, [Anomalies ISL 0 IM].NO3, [Anomalies ISL 0 IM].PO4, [Anomalies ISL 0 IM].SiO3, " "
HAVING ((([Anomalies ISL 0 IM].Cruise)>195000));
